{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, has oral bioavailability ≤3% in patients, demonstrating that sulfated carbohydrate polymers are very poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Dextran sulfate, another sulfated polysaccharide, has poor oral bioavailability in humans, consistent with the query's sulfated sugar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Zanamivir, a polar N-acetyl sugar-like neuraminidase inhibitor with a carboxylic acid, has absolute oral bioavailability of only 2% in healthy volunteers, directly analogous to the query's N-acetyl sugar and carboxylate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acamprosate, a small molecule containing an N-acetyl group and a sulfonate, has absolute oral bioavailability of 11 ± 1% in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "N-acetylcysteine, an N-acetylated polar amino acid, has oral bioavailability of about 10% in healthy subjects, supporting low oral bioavailability for N-acetylated polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Glucoraphanin, a sulfate-containing glycoside, has oral bioavailability of only 5% in humans, supporting low absorption for sulfate-bearing sugar-like molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, ionized sulfated disaccharide (N-acetylglucosamine sulfate linked to glucuronic acid). Multiple structurally related sulfated/polar carbohydrates and N-acetylated polar drugs show absolute oral bioavailability well below 20% (e.g., pentosan polysulfate ≤3%, zanamivir 2%, acamprosate 11%, N-acetylcysteine ~10%, glucoraphanin 5%). Physicochemical properties (TPSA 259, 8 HBD, 13 HBA, logD -16) predict negligible passive permeability. Therefore, oral bioavailability is predicted to be low (<20%).",
  "evidence_gaps": [
    "No direct oral bioavailability data exist for this exact sulfated disaccharide; prediction relies on structurally related analogs.",
    "Potential active uptake or transporter-mediated absorption was not experimentally assessed for the query.",
    "The exact formulation and solubility behavior of the query in oral dosage forms are unknown.",
    "One outlier record for N-acetylcysteine (C04) reports ~80% bioavailability, but it is contradicted by multiple absolute bioavailability studies and is not transferable to the sulfated disaccharide."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

